(6114071, 900210, 77543, '<td valign="top">This would be a super picture if you cropped it tighter to remove the railings on the pier.</td>', 'This would be a super picture if you cropped it tighter to remove the railings on the pier.', '2010-08-02 18:37:51.000000', NULL, 1),
(6114096, 900648, 60698, '<td valign="top">Graceful and pretty. Love all the details in the leaves, contrast and curves! Reminds me of a tree in winter. The leaves keep hanging on even though it is inevitable that they must fall to the ground and enrich the soil. Sigh...Like so many of us... hanging on to the old tried-and-true when we know we should be enriching our minds and souls. Sorry... got a little deep, there. See... what your photo brought out? :)</td>', 'Graceful and pretty. Love all the details in the leaves, contrast and curves! Reminds me of a tree in winter. The leaves keep hanging on even though it is inevitable that they must fall to the ground and enrich the soil. Sigh...Like so many of us... hanging on to the old tried-and-true when we know we should be enriching our minds and souls. Sorry... got a little deep, there. See... what your photo brought out? :)', '2010-08-02 18:49:21.000000', NULL, 1),
(6114156, 898037, 40718, '<td valign="top">His legs make him look dead.</td>', 'His legs make him look dead.', '2010-08-02 19:31:37.000000', NULL, 1),
