(6114580, 899164, 30982, '<td valign="top">Oh I wish this were larger!  You''re allowed 800 pixels on the long side (horizontal in this case.)  Ask in the forums or check under "Learn" to get your submissions to be the full size allowed.  It''s a lovely photo!</td>', 'Oh I wish this were larger!  You''re allowed 800 pixels on the long side (horizontal in this case.)  Ask in the forums or check under "Learn" to get your submissions to be the full size allowed.  It''s a lovely photo!', '2010-08-03 00:51:19.000000', NULL, 1),
(6114592, 900671, 30982, '<td valign="top">When this comes up in the rotation, it really shines.  So beautifully different and inviting!</td>', 'When this comes up in the rotation, it really shines.  So beautifully different and inviting!', '2010-08-03 01:06:19.000000', NULL, 1),
(6114594, 899800, 30982, '<td valign="top">Perfect timing!  What a fun and very professional shot.</td>', 'Perfect timing!  What a fun and very professional shot.', '2010-08-03 01:07:29.000000', NULL, 1),
(6114596, 898274, 30982, '<td valign="top">Magical!  By far one of my favorites of the challenge.  Love these rides - never did get a shot this nice of one, though.</td>', 'Magical!  By far one of my favorites of the challenge.  Love these rides - never did get a shot this nice of one, though.', '2010-08-03 01:08:04.000000', NULL, 1),
(6114597, 899742, 30982, '<td valign="top">Ah, I know this place.  This is amazingly soft light and perfect placement of the moon.  Beautifully done!</td>', 'Ah, I know this place.  This is amazingly soft light and perfect placement of the moon.  Beautifully done!', '2010-08-03 01:08:07.000000', NULL, 1),
(6114598, 898583, 30982, '<td valign="top">The warmth of this shot is wonderful. Contrast of youth versus age, and the glimmer of the trim on the sleeve.  Perfect for B&amp;W, too - keeps it slightly understated.</td>', 'The warmth of this shot is wonderful. Contrast of youth versus age, and the glimmer of the trim on the sleeve.  Perfect for B&W, too - keeps it slightly understated.', '2010-08-03 01:08:49.000000', NULL, 1),
(6114599, 897869, 30982, '<td valign="top">Very striking!  Lovely model and you took wonderful advantage of her features.</td>', 'Very striking!  Lovely model and you took wonderful advantage of her features.', '2010-08-03 01:09:17.000000', NULL, 1),
(6114601, 898552, 30982, '<td valign="top">This cracks me up!  And in pictures, that''s a good thing.  Fun, delightful, and truly enjoyable - thanks!</td>', 'This cracks me up!  And in pictures, that''s a good thing.  Fun, delightful, and truly enjoyable - thanks!', '2010-08-03 01:10:05.000000', NULL, 1),
(6114602, 896486, 30982, '<td valign="top">Awesome use of the lens and an amazing setting.</td>', 'Awesome use of the lens and an amazing setting.', '2010-08-03 01:10:20.000000', NULL, 1),
(6114603, 900751, 30982, '<td valign="top">High key works beautifully here.</td>', 'High key works beautifully here.', '2010-08-03 01:10:30.000000', NULL, 1),
(6114604, 900782, 30982, '<td valign="top">That look combined with the back/rim lighting is just wonderful.  Add rich toning and excellent bokeh, and you''ve got yourself a lovely photograph!</td>', 'That look combined with the back/rim lighting is just wonderful.  Add rich toning and excellent bokeh, and you''ve got yourself a lovely photograph!', '2010-08-03 01:11:38.000000', NULL, 1),
(6114605, 900354, 30982, '<td valign="top">I really like how real and natural this is, and those pink flowers in the foreground are the perfect touch.</td>', 'I really like how real and natural this is, and those pink flowers in the foreground are the perfect touch.', '2010-08-03 01:12:10.000000', NULL, 1),
(6114606, 900645, 30982, '<td valign="top">Great smiles all around!  Fun and warm photo.</td>', 'Great smiles all around!  Fun and warm photo.', '2010-08-03 01:12:43.000000', NULL, 1);
