(6114616, 899262, 30982, '<td valign="top">Wonderful gentle flow!</td>', 'Wonderful gentle flow!', '2010-08-03 01:16:02.000000', NULL, 1),
(6114618, 899517, 30982, '<td valign="top">Really very enjoyable to linger with.</td>', 'Really very enjoyable to linger with.', '2010-08-03 01:16:24.000000', NULL, 1),
(6114619, 897792, 30982, '<td valign="top">And extremely well done.  Made me laugh, actually.  Nice!</td>', 'And extremely well done.  Made me laugh, actually.  Nice!', '2010-08-03 01:17:28.000000', NULL, 1),
(6114620, 900843, 30982, '<td valign="top">Poor dear.  Whatever is that growth on its head?</td>', 'Poor dear.  Whatever is that growth on its head?', '2010-08-03 01:17:42.000000', NULL, 1),
(6114622, 900453, 30982, '<td valign="top">Striking!  The ship works on the right really add nicely to this.</td>', 'Striking!  The ship works on the right really add nicely to this.', '2010-08-03 01:18:47.000000', NULL, 1),
(6114623, 898750, 30982, '<td valign="top">Oh how delightful!</td>', 'Oh how delightful!', '2010-08-03 01:18:56.000000', NULL, 1),
