(6116289, 899290, 113411, '<td valign="top">Fabulous shot! (9)</td>', 'Fabulous shot! (9)', '2010-08-03 23:16:49.000000', NULL, 1),
(6116291, 900610, 113411, '<td valign="top">Really great shot! (8)</td>', 'Really great shot! (8)', '2010-08-03 23:18:02.000000', NULL, 1),
(6116292, 900843, 113411, '<td valign="top">WOW! (8)</td>', 'WOW! (8)', '2010-08-03 23:18:46.000000', NULL, 1),
(6116316, 900704, 114225, '<td valign="top">There is definitely a story behind this photo. Unfortunately, it''s hidden behind the extreme tilting action (just doesn''t add anything in my mind).</td>', 'There is definitely a story behind this photo. Unfortunately, it''s hidden behind the extreme tilting action (just doesn''t add anything in my mind).', '2010-08-03 23:42:10.000000', NULL, 1),
(6116317, 897947, 114225, '<td valign="top">Good separation of subject and background. It could be a bit sharper in the focus area.</td>', 'Good separation of subject and background. It could be a bit sharper in the focus area.', '2010-08-03 23:42:54.000000', NULL, 1),
(6116318, 899759, 114225, '<td valign="top">Great vantage point. Good exposure and compensation.</td>', 'Great vantage point. Good exposure and compensation.', '2010-08-03 23:43:31.000000', NULL, 1),
(6116319, 900932, 114225, '<td valign="top">Cool expansive landscape with good use of both near and bar subjects.<br/>The border really takes away from the beautiful filter. Feels like something that would be added in the GeoCities days (sorry!).</td>', 'Cool expansive landscape with good use of both near and bar subjects.The border really takes away from the beautiful filter. Feels like something that would be added in the GeoCities days (sorry!).', '2010-08-03 23:44:34.000000', NULL, 1),
(6116320, 900207, 114225, '<td valign="top">Really good balance to this photograph. Good use of depth of field and nice colors.</td>', 'Really good balance to this photograph. Good use of depth of field and nice colors.', '2010-08-03 23:45:05.000000', NULL, 1),
(6116323, 900657, 114225, '<td valign="top">Effective use of of selective desaturation. I''m wondering what''s going on with the strange waviness. It adds a bit of fantasy, but takes a lot away from what looks like a great base photo.</td>', 'Effective use of of selective desaturation. I''m wondering what''s going on with the strange waviness. It adds a bit of fantasy, but takes a lot away from what looks like a great base photo.', '2010-08-03 23:46:08.000000', NULL, 1),
(6116325, 898001, 114225, '<td valign="top">Good sharpness in the eyes. The overly soft skin somewhat bothers me. It makes the girl start to look computer generated.</td>', 'Good sharpness in the eyes. The overly soft skin somewhat bothers me. It makes the girl start to look computer generated.', '2010-08-03 23:46:50.000000', NULL, 1),
(6116326, 900869, 114225, '<td valign="top">Good use of leading lines. The power lines on the left remove the sense of balance this photo needs to be effective.</td>', 'Good use of leading lines. The power lines on the left remove the sense of balance this photo needs to be effective.', '2010-08-03 23:47:36.000000', NULL, 1),
(6116327, 899516, 114225, '<td valign="top">Good catch. Nice details in the feathers and nice details in the shadows. The blown out white in the head is pretty distracting.</td>', 'Good catch. Nice details in the feathers and nice details in the shadows. The blown out white in the head is pretty distracting.', '2010-08-03 23:48:28.000000', NULL, 1),
(6116328, 899051, 114225, '<td valign="top">Good natural feeling pose for that time in the pregnancy. I like the use of black and white.</td>', 'Good natural feeling pose for that time in the pregnancy. I like the use of black and white.', '2010-08-03 23:49:11.000000', NULL, 1),
(6116330, 900931, 114225, '<td valign="top">Good job getting the sense  of motion in the water. I know others won''t like the branches that cover the top falls, but I think it adds a bit of mystery.</td>', 'Good job getting the sense  of motion in the water. I know others won''t like the branches that cover the top falls, but I think it adds a bit of mystery.', '2010-08-03 23:49:56.000000', NULL, 1),
(6116331, 900750, 114225, '<td valign="top">Great job stoping the action. Good focus on the subjects and nice low vantage point.</td>', 'Great job stoping the action. Good focus on the subjects and nice low vantage point.', '2010-08-03 23:50:27.000000', NULL, 1),
(6116332, 900809, 114225, '<td valign="top">Cool subject. This looks like a great use of the fish eye lens. I like the cool/metallic colors.</td>', 'Cool subject. This looks like a great use of the fish eye lens. I like the cool/metallic colors.', '2010-08-03 23:50:59.000000', NULL, 1),
