(6122009, 899262, 67258, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2010-08-07 16:55:15.000000', NULL, 1),
(6122013, 897947, 67258, '<td valign="top">A perfect title for the image.  Wonderful softness and muted colours, yet displays a very real sense of vibrancy and life.</td>', 'A perfect title for the image.  Wonderful softness and muted colours, yet displays a very real sense of vibrancy and life.', '2010-08-07 16:55:50.000000', NULL, 1),
