(6122020, 900485, 108580, '<td valign="top">Beautiful</td>', 'Beautiful', '2010-08-07 17:02:58.000000', NULL, 1),
(6122026, 898001, 37845, '<td valign="top">Andy, I recognize this shot from your flickr profile, and I think this is as brilliant as your entry from last month. Good luck (no vote)</td>', 'Andy, I recognize this shot from your flickr profile, and I think this is as brilliant as your entry from last month. Good luck (no vote)', '2010-08-07 17:24:04.000000', NULL, 1),
(6122028, 900754, 37845, '<td valign="top">If I had to guess, I would say that this is timfythetoo''s shot. The high key black and white on this is perfect. no vote.</td>', 'If I had to guess, I would say that this is timfythetoo''s shot. The high key black and white on this is perfect. no vote.', '2010-08-07 17:25:32.000000', NULL, 1),
(6122031, 900657, 37845, '<td valign="top">I''d be interested to see what kind of filter/plugin you used to get this effect.</td>', 'I''d be interested to see what kind of filter/plugin you used to get this effect.', '2010-08-07 17:31:33.000000', NULL, 1),
(6122032, 899164, 37845, '<td valign="top">Too bad that this image is so small. With the proper size, it would have more impact.</td>', 'Too bad that this image is so small. With the proper size, it would have more impact.', '2010-08-07 17:32:24.000000', NULL, 1),
(6122035, 897986, 37845, '<td valign="top">I must have looked at this shot half a dozen times now, racking my brain as to where I have seen it before. I checked the challenge archives, thinking this was an outtake, but to no avail. Then, it dawned on my... photographycorner.com. Great image Neil, and no doubt it will also do well here. No vote.</td>', 'I must have looked at this shot half a dozen times now, racking my brain as to where I have seen it before. I checked the challenge archives, thinking this was an outtake, but to no avail. Then, it dawned on my... photographycorner.com. Great image Neil, and no doubt it will also do well here. No vote.', '2010-08-07 17:34:37.000000', NULL, 1),
(6122037, 899823, 37845, '<td valign="top">Not a pretty picture by any means, but very effective at conveying a particular sub culture. Great shot.</td>', 'Not a pretty picture by any means, but very effective at conveying a particular sub culture. Great shot.', '2010-08-07 17:38:21.000000', NULL, 1),
