INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6122430, 900509, 51747, '<td valign="top">This is a really good shot of a most interesting moth.</td>', 'This is a really good shot of a most interesting moth.', '2010-08-08 00:09:53.000000', NULL, 1),
(6122431, 899747, 51747, '<td valign="top">Really nice.</td>', 'Really nice.', '2010-08-08 00:11:13.000000', NULL, 1),
(6122433, 900740, 51747, '<td valign="top">Sweet!</td>', 'Sweet!', '2010-08-08 00:11:28.000000', NULL, 1),
(6122434, 900850, 32011, '<td valign="top">One of my two favourite photos in this FS.  Fantastic composition, detail and colour... minimalism at it''s finest.  Love your work and I''ve given it a 10 (after initially giving it an 8).</td>', 'One of my two favourite photos in this FS.  Fantastic composition, detail and colour... minimalism at it''s finest.  Love your work and I''ve given it a 10 (after initially giving it an 8).', '2010-08-08 00:11:44.000000', NULL, 1),
(6122437, 900497, 51747, '<td valign="top">Pretty amazing detail here. Excellent work!</td>', 'Pretty amazing detail here. Excellent work!', '2010-08-08 00:12:13.000000', NULL, 1),
(6122438, 900816, 51747, '<td valign="top">You have a good imagination :D Nice title.</td>', 'You have a good imagination :D Nice title.', '2010-08-08 00:12:26.000000', NULL, 1),
(6122439, 898827, 51747, '<td valign="top">Nice action shot. Too bad his arm is not completely in the frame.</td>', 'Nice action shot. Too bad his arm is not completely in the frame.', '2010-08-08 00:12:38.000000', NULL, 1),
(6122440, 899235, 51747, '<td valign="top">It''s a pretty cool looking scene. Maybe just a bit more brightening and straightening would really make this pop.</td>', 'It''s a pretty cool looking scene. Maybe just a bit more brightening and straightening would really make this pop.', '2010-08-08 00:12:57.000000', NULL, 1),
(6122441, 898983, 51747, '<td valign="top">You have captured her very nicely. Not sure what it is about the lighting that isn''t quite right...</td>', 'You have captured her very nicely. Not sure what it is about the lighting that isn''t quite right...', '2010-08-08 00:12:59.000000', NULL, 1),
(6122442, 900556, 51747, '<td valign="top">I''m not sure how you did this but it looks pretty cool.</td>', 'I''m not sure how you did this but it looks pretty cool.', '2010-08-08 00:13:08.000000', NULL, 1),
(6122443, 900649, 51747, '<td valign="top">Cute</td>', 'Cute', '2010-08-08 00:13:12.000000', NULL, 1),
(6122444, 900581, 51747, '<td valign="top">Cool perspective.</td>', 'Cool perspective.', '2010-08-08 00:13:31.000000', NULL, 1),
(6122445, 900782, 51747, '<td valign="top">I love the back lighting.</td>', 'I love the back lighting.', '2010-08-08 00:13:32.000000', NULL, 1),
(6122469, 900858, 83313, '<td valign="top">You''ve got an unbelievable amount of JPEG compression showing here. Fortunately, due to the nature of your scene, it comes off looking more like an artistic treatment than the compression artifacts that this really is showing. At 28k file size, you had a ton of overhead you could have used. I''d love to see a version of this with less compression. It looks like it could be a wonderful scene. Always use the least compression you can get away with and still come in under challenge limits.</td>', 'You''ve got an unbelievable amount of JPEG compression showing here. Fortunately, due to the nature of your scene, it comes off looking more like an artistic treatment than the compression artifacts that this really is showing. At 28k file size, you had a ton of overhead you could have used. I''d love to see a version of this with less compression. It looks like it could be a wonderful scene. Always use the least compression you can get away with and still come in under challenge limits.', '2010-08-08 00:30:05.000000', NULL, 1),
(6122471, 900939, 63218, '<td valign="top">Delightfully subtle &amp; yet glorious. Very nice light.</td>', 'Delightfully subtle & yet glorious. Very nice light.', '2010-08-08 00:31:47.000000', NULL, 1),
(6122472, 900765, 32011, '<td valign="top">Absolutely beautiful emotive portrait.  Excellent use of shallow DOF.  Perfect composition.  One of my two favourite images in this FS.  Like the other, I initially gave it an 8 and have bumped it to a 10 on second pass.  Well done.</td>', 'Absolutely beautiful emotive portrait.  Excellent use of shallow DOF.  Perfect composition.  One of my two favourite images in this FS.  Like the other, I initially gave it an 8 and have bumped it to a 10 on second pass.  Well done.', '2010-08-08 00:32:36.000000', NULL, 1),
(6122474, 899262, 32011, '<td valign="top">Beautiful image.  Well composed and imaginative... can see this on a wall in my house if it wasn''t so pink  :)  Excellent job.</td>', 'Beautiful image.  Well composed and imaginative... can see this on a wall in my house if it wasn''t so pink  :)  Excellent job.', '2010-08-08 00:34:05.000000', NULL, 1),
(6122475, 899213, 63218, '<td valign="top">How cute is this!</td>', 'How cute is this!', '2010-08-08 00:34:45.000000', NULL, 1),
(6122476, 899262, 63218, '<td valign="top">Sharp and soft at the same time, &amp; such a lovely peppermint pink--this would look great on a perfume label.  I like the way you''ve captured both sun and wind in this, &amp; the way you cropped it, too.  Please accept the Gilded Lily and my humble admiration for an excellent floral comp--well done! <br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=831779" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg"/></a> <br/><br/><br/><i>Message edited by author 2010-08-08 00:26:40.</i></td>', 'Sharp and soft at the same time, & such a lovely peppermint pink--this would look great on a perfume label.  I like the way you''ve captured both sun and wind in this, & the way you cropped it, too.  Please accept the Gilded Lily and my humble admiration for an excellent floral comp--well done!   ', '2010-08-08 00:35:25.000000', '2010-08-08 01:26:40.000000', 1),
(6122477, 900648, 32011, '<td valign="top">I love this photo.  Simple, detailed, well balanced... composition is excellent.  Up there as one of my top 10 favourites in the FS.</td>', 'I love this photo.  Simple, detailed, well balanced... composition is excellent.  Up there as one of my top 10 favourites in the FS.', '2010-08-08 00:35:47.000000', NULL, 1),
(6122478, 900328, 63218, '<td valign="top">These spikes of small flowers are a challenge to capture well, this one is excllent, mainly I think because of the light.  The BG is interesting, &amp; complementary (chain-link fence?). DOF leads my eye right to the main subject.  Please accept this Gilded Lily &amp; my humble admiration for a great floral capture!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=831779" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_831779.jpg"/></a></td>', 'These spikes of small flowers are a challenge to capture well, this one is excllent, mainly I think because of the light.  The BG is interesting, & complementary (chain-link fence?). DOF leads my eye right to the main subject.  Please accept this Gilded Lily & my humble admiration for a great floral capture!', '2010-08-08 00:35:50.000000', NULL, 1),
(6122479, 899517, 63218, '<td valign="top">This is so much fun to look at it, I stopped voting for a while.</td>', 'This is so much fun to look at it, I stopped voting for a while.', '2010-08-08 00:36:19.000000', NULL, 1),
(6122480, 900781, 32011, '<td valign="top">This image has a WOW factor.  Sharp and crisp... and you''ve nailed to composition too.  Well done.</td>', 'This image has a WOW factor.  Sharp and crisp... and you''ve nailed to composition too.  Well done.', '2010-08-08 00:36:44.000000', NULL, 1),
(6122487, 900867, 32011, '<td valign="top">Great use of colour and leading lines... one of my top 10 favourites in the FS, and easily my favourite street photo of the lot.  Well done.</td>', 'Great use of colour and leading lines... one of my top 10 favourites in the FS, and easily my favourite street photo of the lot.  Well done.', '2010-08-08 00:40:23.000000', NULL, 1),
(6122488, 900621, 83313, '<td valign="top">Bah, mess is bad. Grog is great keeper-of-cave, will give advice. You keep cave clean to impress females. Sweep with matted straw and use large bush outside for personal matters. This impress females, but Grog not understand why. Once  female bear younglings for you, then you do as wanting again. You thank Grog and offer many faves and comments for him.</td>', 'Bah, mess is bad. Grog is great keeper-of-cave, will give advice. You keep cave clean to impress females. Sweep with matted straw and use large bush outside for personal matters. This impress females, but Grog not understand why. Once  female bear younglings for you, then you do as wanting again. You thank Grog and offer many faves and comments for him.', '2010-08-08 00:41:03.000000', NULL, 1),
(6122493, 900794, 83313, '<td valign="top">Grog knows redecorating of cave is sign of youngling on way. Grog say congratulations.</td>', 'Grog knows redecorating of cave is sign of youngling on way. Grog say congratulations.', '2010-08-08 00:43:09.000000', NULL, 1),
(6122496, 900857, 83313, '<td valign="top">Other than the need for a touch of noise reduction in the sky, I love this.</td>', 'Other than the need for a touch of noise reduction in the sky, I love this.', '2010-08-08 00:45:26.000000', NULL, 1),
(6122499, 896427, 15711, '<td valign="top">I like the vignette. Almost has an old fashioned post card feel to it.</td>', 'I like the vignette. Almost has an old fashioned post card feel to it.', '2010-08-08 00:47:10.000000', NULL, 1),
(6122501, 896126, 15711, '<td valign="top">I love the contrast against the black.  Tack sharp focus!  NICE.</td>', 'I love the contrast against the black.  Tack sharp focus!  NICE.', '2010-08-08 00:48:41.000000', NULL, 1),
(6122503, 900825, 32011, '<td valign="top">Wonderful capture, and fantastic processing.  One of my top 10 favourites in the FS.  Great job on this image...</td>', 'Wonderful capture, and fantastic processing.  One of my top 10 favourites in the FS.  Great job on this image...', '2010-08-08 00:49:24.000000', NULL, 1),
(6122504, 900964, 32011, '<td valign="top">This is spectacular for its brilliant minimalism.  Composition is perfect... originally gave this an 8, then bumped it to a 9, and now, looking at it to comment I think it deserves a further bump... so, a 10 and a fav too for good measure.  Love this image so much.</td>', 'This is spectacular for its brilliant minimalism.  Composition is perfect... originally gave this an 8, then bumped it to a 9, and now, looking at it to comment I think it deserves a further bump... so, a 10 and a fav too for good measure.  Love this image so much.', '2010-08-08 00:49:48.000000', NULL, 1),
(6122506, 900948, 15711, '<td valign="top">I love this.  Great title too.</td>', 'I love this.  Great title too.', '2010-08-08 00:51:01.000000', NULL, 1),
(6122508, 900874, 15711, '<td valign="top">Perfect focus.</td>', 'Perfect focus.', '2010-08-08 00:52:16.000000', NULL, 1),
(6122509, 898750, 83313, '<td valign="top">Hunt has been successful! Grog (with small help of Thag and Kron) brings home mammoth for tribe. All tribe celebrates outside cave. Younglings do ancient dance of plenty. Much joy is had. Except for Krag (on left). Krag is picky eater (Krag says he "gormay"). Does not like mammoth meat. Wants quiche and fondue. Grog think Krag is little funny.</td>', 'Hunt has been successful! Grog (with small help of Thag and Kron) brings home mammoth for tribe. All tribe celebrates outside cave. Younglings do ancient dance of plenty. Much joy is had. Except for Krag (on left). Krag is picky eater (Krag says he "gormay"). Does not like mammoth meat. Wants quiche and fondue. Grog think Krag is little funny.', '2010-08-08 00:55:14.000000', NULL, 1),
