INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6122786, 900756, 72670, '<td valign="top">Wow!! I thought the DPC crowd would be all over this! Surprising finish.</td>', 'Wow!! I thought the DPC crowd would be all over this! Surprising finish.', '2010-08-08 08:15:06.000000', NULL, 0),
(6122788, 900740, 118154, '<td valign="top">This is a superb shot,(its not the tools by the way) Congrats it was a 9 from me and I,m a very low scorer.</td>', 'This is a superb shot,(its not the tools by the way) Congrats it was a 9 from me and I,m a very low scorer.', '2010-08-08 08:24:22.000000', NULL, 0),
(6122789, 899747, 27133, '<td valign="top">Nice score...but definitely the right choice for the challenge.  And who cares about her hand and foot...her pose, grace and beauty command the shot...no need for anything else.  Oh...and having a good photographer helps I suppose....hehehehehe!</td>', 'Nice score...but definitely the right choice for the challenge.  And who cares about her hand and foot...her pose, grace and beauty command the shot...no need for anything else.  Oh...and having a good photographer helps I suppose....hehehehehe!', '2010-08-08 08:26:44.000000', NULL, 0),
(6122797, 899262, 100393, '<td valign="top">I feel a little sheepish that I only scored this a 6 - on a second look I think it is much better than that. I should''ve given it more time.</td>', 'I feel a little sheepish that I only scored this a 6 - on a second look I think it is much better than that. I should''ve given it more time.', '2010-08-08 08:51:18.000000', NULL, 0),
(6122800, 900740, 113278, '<td valign="top">Awesome job and great finish. Big congrats</td>', 'Awesome job and great finish. Big congrats', '2010-08-08 09:03:16.000000', NULL, 0),
(6122801, 898825, 117474, '<td valign="top">Wow... I was sure that''d do far far better than it did. I was one of your four 9''s. <br/>Nice soft lighting. Great composure. Nice DOF. Good use of negative space. <br/>I was looking for this when I was going through the top few pages of the competition entries and was surprised to not see it. The only thing I''d change with it is on the top over her right shoulder there''s a bit of something black popping down. In advanced editing (I believe) you could have cloned that out as it wasn''t a major constituent of the shot. Otherwise you might have been able to crop it out. Or make a boarder disguise it or something. <br/>Again, excellent work.</td>', 'Wow... I was sure that''d do far far better than it did. I was one of your four 9''s. Nice soft lighting. Great composure. Nice DOF. Good use of negative space. I was looking for this when I was going through the top few pages of the competition entries and was surprised to not see it. The only thing I''d change with it is on the top over her right shoulder there''s a bit of something black popping down. In advanced editing (I believe) you could have cloned that out as it wasn''t a major constituent of the shot. Otherwise you might have been able to crop it out. Or make a boarder disguise it or something. Again, excellent work.', '2010-08-08 09:11:04.000000', NULL, 0),
(6122803, 900950, 51747, '<td valign="top">You captured the perfect moment here. Nice score too!</td>', 'You captured the perfect moment here. Nice score too!', '2010-08-08 09:28:24.000000', NULL, 0),
(6122805, 899747, 51747, '<td valign="top">Such a good shot. I had this in my top 8. The light is wonderful.</td>', 'Such a good shot. I had this in my top 8. The light is wonderful.', '2010-08-08 09:31:31.000000', NULL, 0),
